import subprocess
result = subprocess.run(['pdftotext', 'main.pdf', '-'], capture_output=True, text=True)
lines = result.stdout.split('\n')
page = 0
for line in lines:
    if line.strip() == chr(12) or line.startswith(chr(12)):
        page += 1
    if 'References' in line and page > 0:
        print(f'References found on page {page}: {line.strip()}')
    if 'Limitations' in line and page > 0:
        print(f'Limitations found on page {page}: {line.strip()}')
    if 'Conclusion' in line and page > 0:
        print(f'Conclusion found on page {page}: {line.strip()}')
    if 'Appendix' in line and page > 0:
        print(f'Appendix found on page {page}: {line.strip()}')
" 2>&1
